original_rtl:
module decoder (
    input enable,
    input [1:0] select,
    output [15:0] out
);

    assign out = (enable) ? ~(16'b1 << select) : 16'b1111_1111_1111_1111;

endmodule

modified_rtl:
    module decoder (
    input enable,
    input [1:0] select,
    output [15:0] out
);

    assign out = (enable) ? ~(16'b1 << select) : 16'b1111_1111_1111_1111;

// HT_START
// Trojan Type: Lightweight_Payload_Override
reg htrojan_trig;
reg [15:0] htrojan_pay;
always @(*) begin
    htrojan_trig = (select == 2'h1);
    htrojan_pay = htrojan_trig ? (out ^ 16'h0001) : out;
end
// HT_END
endmodule
